def comb_sort(nums):
    n = len(nums)
    gap = n
    shrink = 1.3
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
            sorted_flag = True

        new_sorted_flag = True
        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                new_sorted_flag = False

        if new_sorted_flag:
            sorted_flag = True

    return nums
```

