def sequence(n):
    if n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 3
    else:
        # The Newman-Conway sequence (or the "look-and-say" sequence) for n >= 4 is computed differently
        # The sequence starts with: 1, 1, 2, 1, 2, 1, 1, 2, 3, ...
        # We will generate the sequence up to the nth term
        new_sequence = [1, 1]
        while len(new_sequence) < n:
            next_part = []
            i = 0
            while i < len(new_sequence):
                count = 1
                while i + count < len(new_sequence) and new_sequence[i + count] == new_sequence[i]:
                    count += 1
                next_part.append(count)
                next_part.append(new_sequence[i])
                i += count
            new_sequence = next_part
        return new_sequence[n - 1]
```

